package main

import (
	"testing"

	story "ofam.dev/monogatari"
)

// Persistent state needs a real restart, not a composite fixture reset.
func TestRestartKeepsTableAndPaneState(t *testing.T) {
	for _, data := range []string{
		"{\"name\":\"a row-select table pins a column from the palette, keeps it across a restart, and reset-columns puts the default pins back (R5.13)\",\"area\":\"tables\",\"width\":40,\"height\":8,\"chrome\":\"none\",\"page\":{\"noHeadings\":true,\"lists\":[{\"id\":\"t\",\"columns\":[{\"title\":\"name\",\"width\":8},{\"title\":\"alpha\",\"width\":8},{\"title\":\"bravo\",\"width\":8},{\"title\":\"charlie\",\"width\":8},{\"title\":\"delta\",\"width\":8},{\"title\":\"echo\",\"width\":8}],\"items\":[{\"id\":\"t1\",\"label\":\"row1\",\"cells\":[\"row1\",\"a-1\",\"b-1\",\"c-1\",\"d-1\",\"e-1\"]},{\"id\":\"t2\",\"label\":\"row2\",\"cells\":[\"row2\",\"a-2\",\"b-2\",\"c-2\",\"d-2\",\"e-2\"]},{\"id\":\"t3\",\"label\":\"row3\",\"cells\":[\"row3\",\"a-3\",\"b-3\",\"c-3\",\"d-3\",\"e-3\"]}]}],\"focus\":\"t1\"},\"script\":[\":\",{\"type\":\"toggle-pin-column delta\"},\"enter\",{\"restart\":true},\":\",{\"type\":\"reset-columns\"},\"enter\"],\"expect\":[{\"after\":3,\"modal\":\"\",\"order\":[\"name\",\"delta\",\"alpha\"]},{\"after\":4,\"order\":[\"name\",\"delta\",\"alpha\"]},{\"after\":7,\"modal\":\"\",\"order\":[\"name\",\"alpha\",\"bravo\"],\"lacks\":[\"delta\"]}],\"state\":true}",
		"{\"name\":\"column widths: z > widens the current column, the width and the column survive a restart, z = makes it automatic\",\"width\":60,\"height\":6,\"chrome\":\"none\",\"state\":true,\"page\":{\"noHeadings\":true,\"lists\":[{\"id\":\"t\",\"cellSelect\":true,\"columns\":[{\"title\":\"pane\"},{\"title\":\"harness\",\"priority\":2},{\"title\":\"state\",\"priority\":1},{\"title\":\"cwd\",\"min\":8,\"priority\":3},{\"title\":\"branch\",\"priority\":4}],\"items\":[{\"id\":\"t1\",\"label\":\"work/claude\",\"cells\":[\"work/claude\",\"claude-code\",\"idle\",\"~/proj/matomeru\",\"main\"]},{\"id\":\"t2\",\"label\":\"work/codex\",\"cells\":[\"work/codex\",\"codex\",\"working\",\"~/proj/ochazuke\",\"feat/list-motions\"]},{\"id\":\"t3\",\"label\":\"main/shell\",\"cells\":[\"main/shell\",\"shell\",\"\",\"~/hub\",\"docs/readme-header\"]},{\"id\":\"t4\",\"label\":\"9332c352/review\",\"cells\":[\"9332c352/review\",\"claude-code\",\"needs_input\",\"~/proj/nabe\",\"prototype/picker-lab\"]}],\"selected\":0}]},\"script\":[\"l\",\"l\",\"z\",\">\",\"z\",\">\",{\"restart\":true},\"z\",\"=\"],\"expect\":[{\"after\":6,\"contains\":[\"state            cwd\"],\"cell\":\"idle\"},{\"after\":7,\"contains\":[\"state            cwd\"],\"cell\":\"idle\"},{\"contains\":[\"state        cwd\"],\"lacks\":[\"state            cwd\"],\"cell\":\"idle\"}],\"area\":\"tables\"}",
		"{\"name\":\"z F on a row-select table fits every column it can and narrows the widest (note) so only it is cut; the widths survive a restart and the cursor moves nothing; z = undoes it\",\"area\":\"tables\",\"width\":60,\"height\":10,\"chrome\":\"none\",\"state\":true,\"page\":{\"noHeadings\":true,\"lists\":[{\"id\":\"t\",\"columns\":[{\"title\":\"name\"},{\"title\":\"note\",\"max\":12},{\"title\":\"size\"},{\"title\":\"kind\"}],\"items\":[{\"id\":\"r1\",\"label\":\"r1\",\"cells\":[\"r1\",\"short\",\"7\",\"file-of-kind-r1\"]},{\"id\":\"r2\",\"label\":\"r2\",\"cells\":[\"r2\",\"short\",\"7\",\"file-of-kind-r2\"]},{\"id\":\"r3\",\"label\":\"r3\",\"cells\":[\"r3\",\"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn\",\"7\",\"file-of-kind-r3\"]},{\"id\":\"r4\",\"label\":\"r4\",\"cells\":[\"r4\",\"short\",\"7\",\"file-of-kind-r4\"]},{\"id\":\"r5\",\"label\":\"r5\",\"cells\":[\"r5\",\"short\",\"7\",\"file-of-kind-r5\"]},{\"id\":\"r6\",\"label\":\"r6\",\"cells\":[\"r6\",\"short\",\"7\",\"file-of-kind-r6\"]}],\"selected\":0}]},\"script\":[\"z\",\"F\",\"j\",\"j\",{\"restart\":true},\"j\",\"z\",\"=\"],\"expect\":[{\"after\":2,\"contains\":[\"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnn…\",\"file-of-kind-r1\"],\"lacks\":[\"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn\"]},{\"after\":4,\"contains\":[\"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnn…\",\"file-of-kind-r1\"],\"lacks\":[\"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn\"]},{\"after\":6,\"contains\":[\"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnn…\",\"file-of-kind-r1\"],\"lacks\":[\"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn\"]},{\"contains\":[\"r3    nnnnnnnnnnn…\"],\"lacks\":[\"nnnnnnnnnnnnnnnnnnnnnnnnn\"]}]}",
		"{\"name\":\"panes: the divider is remembered per page across a restart (the state dir's panes.json)\",\"area\":\"panes\",\"width\":100,\"height\":22,\"state\":true,\"page\":{\"id\":\"ai\",\"title\":\"AI\",\"catalog\":{\"nouns\":[{\"name\":\"skill\",\"columns\":[{\"title\":\"Name\",\"min\":8},{\"title\":\"Origin\"}],\"verbs\":[{\"name\":\"list\",\"rows\":\"skill\"},{\"name\":\"show\"}]},{\"name\":\"mcp\",\"verbs\":[{\"name\":\"tools\",\"rows\":\"mcp-tool\"}]},{\"name\":\"mcp-tool\",\"verbs\":[{\"name\":\"show\"}]}],\"page\":{\"title\":\"AI\",\"lists\":[{\"id\":\"ai/skills\",\"noun\":\"skill\"},{\"id\":\"ai/tools\",\"noun\":\"mcp\",\"source\":\"mcp.tools\",\"title\":\"tools\"}],\"layout\":\"split\",\"detail\":{\"title\":\"record\"}},\"answers\":{\"skill.list\":[{\"id\":\"s1\",\"name\":\"architect\",\"cells\":[\"architect\",\"claude\"],\"path\":\"~/.claude/skills/architect\",\"origin\":\"claude\"},{\"id\":\"s2\",\"name\":\"review\",\"cells\":[\"review\",\"ai-tools\"],\"path\":\"~/proj/ai-tools/review\",\"origin\":\"ai-tools\"}],\"mcp.tools\":\"{\\\"noun\\\":\\\"mcp\\\",\\\"id\\\":\\\"t1\\\",\\\"label\\\":\\\"tuios_send_text\\\",\\\"data\\\":{\\\"server\\\":\\\"tuios\\\"}}\\n{\\\"noun\\\":\\\"mcp\\\",\\\"id\\\":\\\"t2\\\",\\\"label\\\":\\\"tuios_capture\\\",\\\"data\\\":{\\\"server\\\":\\\"tuios\\\"}}\\n\"}}},\"script\":[\"ctrl+w\",\">\",\"ctrl+w\",\">\",{\"restart\":true}],\"expect\":[{\"after\":4,\"shift\":10,\"contains\":[\"┏━ skill (2) ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓ ╭─ record\"]},{\"shift\":10,\"focus\":\"ai/skills/s1\",\"contains\":[\"┏━ skill (2) ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓ ╭─ record\"]}]}",
	} {
		s, err := story.Parse([]byte(data), "restart regression")
		if err != nil {
			t.Fatal(err)
		}
		t.Run(story.Slug(s.Name), func(t *testing.T) {
			res := (story.Library{Apps: hostApps}).Run(s, story.RunOptions{})
			if res.Err != nil {
				t.Fatal(res.Err)
			}
			for _, failure := range res.Failed {
				t.Error(failure)
			}
		})
	}
}
